<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Plan;final class PlanController extends AdminController{public function index(Request $k):Response{return $this->view('admin/plans/index',['plans'=>Plan::all('sort'),'meta'=>['title'=>t('admin.plans')]]);}public function edit(Request $i,?string $a=null):Response{$U=$a?Plan::find((int)$a):null;return $this->view('admin/plans/edit',['plan'=>$U,'allFeatures'=>Plan::ALL_FEATURES,'meta'=>['title'=>$U?t('common.edit'):t('common.create')]]);}public function save(Request $k):Response{if($z=$this->validate($k,['slug'=>'required|slug|max:32','price_month'=>'required|numeric','price_year'=>'required|numeric','retention_days'=>'required|int'],'/admin/plans')){return $z;}$w=$k->int('id');$m=['slug'=>$k->str('slug'),'name'=>$this->multilang($k->input('name')),'description'=>$this->multilang($k->input('description')),'price_month'=>(int)round((float)str_replace(',','.',$k->str('price_month'))*100),'price_year'=>(int)round((float)str_replace(',','.',$k->str('price_year'))*100),'currency'=>strtoupper($k->str('currency')?:'EUR'),'max_cameras'=>$k->str('max_cameras')===''?null:$k->int('max_cameras'),'retention_days'=>$k->int('retention_days'),'features'=>array_values(array_intersect((array)$k->input('features',[]),Plan::ALL_FEATURES)),'highlights'=>$this->multilang($k->input('highlights')),'trial_days'=>$k->int('trial_days'),'stripe_price_month'=>$k->str('stripe_price_month')?:null,'stripe_price_year'=>$k->str('stripe_price_year')?:null,'sort'=>$k->int('sort'),'is_public'=>$k->bool('is_public')?1:0,'is_active'=>$k->bool('is_active')?1:0,'is_featured'=>$k->bool('is_featured')?1:0];$T=Plan::findBySlug($m['slug']);if($T&&(int)$T['id']!==$w){$this->flash('error',t('admin.slug_taken'));return $this->redirect('/admin/plans');}if($w){Plan::update($w,$m);}else{$w=Plan::create($m);}AuditLog::log('admin.plan_save',$m['slug']);$this->flash('success',t('common.saved'));return $this->redirect('/admin/plans/'.$w);}}